import{_ as d,o as e,a as s,b as r}from"./app.BGziXukh.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/technical_appendix"},{"text":"C++标准支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_standard_support"},{"text":"Device侧C++语言支持","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp_language_feature"},{"text":"C++11语言特性","link":"/guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp11_language_feature"}]},"headers":[],"relativePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp11_language_feature.md","filePath":"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp11_language_feature.md","lastUpdated":1794790922000}'),c={name:"guide/technical_appendix/cpp_standard_support/cpp_language_feature/cpp11_language_feature.md"};function p(o,t,a,w,n,h){return e(),s("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>C++11语言特性</h1><p>本文介绍C++11语言特性在Ascend C Device侧的支持情况。</p><p>下表汇总了Device侧对C++11核心语言特性的支持情况：</p><table><thead><tr><th>C++11特性</th><th>C++11 Proposal</th><th>是否支持</th><th>说明</th></tr></thead><tbody><tr><td>右值引用</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2006/n2118.html">N2118</a></td><td>是</td><td>支持右值引用形参、移动构造与移动赋值。</td></tr><tr><td><code>*this</code>的右值引用（Rvalue references for <code>*this</code>）</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2439.htm">N2439</a></td><td>是</td><td>支持<code>func() &amp;</code>、<code>func() &amp;&amp;</code>、<code>func() const &amp;</code>引用限定成员函数重载。</td></tr><tr><td>右值初始化类对象</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1610.html">N1610</a></td><td>是</td><td>工厂函数返回右值时移动构造或返回值优化均生效。</td></tr><tr><td>非静态数据成员初始化器</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2756.htm">N2756</a></td><td>是</td><td>类内成员默认初始化器可用，构造对象时未显式初始化的成员取默认值。</td></tr><tr><td>变参模板</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2242.pdf">N2242</a></td><td>是</td><td>支持参数包、<code>sizeof...</code>、包展开进数组初始化、函数实参、基类列表，递归继承展开。</td></tr><tr><td>扩展变参模板模板参数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2555.pdf">N2555</a></td><td>是</td><td>模板模板形参可接受变参模板实参。</td></tr><tr><td>初始化列表</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2672.htm">N2672</a></td><td>部分</td><td>聚合、数组与类对象的花括号初始化在Device侧可用；<code>std::initializer_list</code>的begin、size为Host函数，基于它的构造与遍历在Device侧编译报<code>reference to __host__ function</code>，需要变长初始化时以数组或变参模板替代。</td></tr><tr><td>静态断言</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1720.html">N1720</a></td><td>是</td><td>支持命名空间级与函数内<code>static_assert</code>，可在模板中使用。</td></tr><tr><td>auto类型变量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2006/n1984.pdf">N1984</a></td><td>是</td><td>支持从初始化表达式、lambda表达式推导类型。注意Host侧<code>auto dev = nullptr;</code>声明的设备指针经<code>aclrtMalloc</code>传入核函数时Device地址不生效，设备指针应以显式指针类型声明。</td></tr><tr><td>多声明符auto</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1737.pdf">N1737</a></td><td>是</td><td>一条语句声明多个auto变量，要求各声明符推导类型一致，不一致时编译报错。</td></tr><tr><td>移除auto存储类说明符</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2546.htm">N2546</a></td><td>是</td><td>auto不再作为存储类说明符，仅保留类型推导语义。</td></tr><tr><td>新函数声明符语法</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2541.htm">N2541</a></td><td>是</td><td>支持尾置返回类型<code>auto f(...) -&gt; T</code>，与decltype配合推导返回类型。</td></tr><tr><td>Lambda表达式</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2009/n2927.pdf">N2927</a></td><td>是</td><td>SIMD与SIMT混合编程场景需显式标记函数属性，详见<a href="./lambda_expressions.html">Lambda表达式</a>。</td></tr><tr><td>表达式的声明类型（Declared type of an expression，decltype）</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2343.pdf">N2343</a></td><td>是</td><td>值类别语义与标准一致：具名实体推导声明类型，表达式按左值、右值推导引用。</td></tr><tr><td>不完整返回类型</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2011/n3276.pdf">N3276</a></td><td>是</td><td>允许函数声明返回不完整类型，定义时类型须完整。</td></tr><tr><td>右尖括号</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2005/n1757.html">N1757</a></td><td>是</td><td>嵌套模板关闭符<code>&gt;&gt;</code>无需空格分隔。</td></tr><tr><td>函数模板默认模板实参</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/cwg_defects.html#226">DR226</a></td><td>是</td><td>函数模板形参可带默认模板实参。</td></tr><tr><td>表达式SFINAE</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2634.html">DR339</a></td><td>是</td><td>替换失败发生在表达式与类型推导中时按SFINAE处理，不报硬错误。</td></tr><tr><td>别名模板</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2258.pdf">N2258</a></td><td>是</td><td>支持<code>template &lt;typename T&gt; using Alias = ...</code>及元函数级联。</td></tr><tr><td>外部模板</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2006/n1987.htm">N1987</a></td><td>是</td><td>支持<code>extern template</code>显式实例化声明，抑制隐式实例化。</td></tr><tr><td>空指针常量（Null pointer constant，nullptr）</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2431.pdf">N2431</a></td><td>是</td><td>支持nullptr初始化、比较与函数重载决议。</td></tr><tr><td>强类型枚举</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2347.pdf">N2347</a></td><td>是</td><td>支持enum class及底层类型指定。</td></tr><tr><td>枚举前向声明</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2764.pdf">N2764</a>、<a href="https://cplusplus.github.io/CWG/issues/1206.html">DR1206</a></td><td>是</td><td><code>enum class E : 底层类型;</code>可先声明后定义，底层类型须显式指定。</td></tr><tr><td>标准化属性语法</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2761.pdf">N2761</a></td><td>是</td><td>支持<code>[[...]]</code>标准属性语法，如<code>[[noreturn]]</code>。</td></tr><tr><td>广义常量表达式</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2235.pdf">N2235</a></td><td>是</td><td>constexpr变量可作数组尺寸与模板实参，constexpr函数可在编译期求值。</td></tr><tr><td>对齐支持</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2341.pdf">N2341</a></td><td>是</td><td>支持alignas、alignof，可作用于类、全局与局部变量。</td></tr><tr><td>条件支持行为</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1627.pdf">N1627</a></td><td>是</td><td><code>__int128</code>扩展整型在Device侧可用。</td></tr><tr><td>未定义行为转为可诊断错误</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1727.pdf">N1727</a></td><td>是</td><td>标准要求可诊断的未定义行为按编译错误或告警处理。</td></tr><tr><td>委托构造函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2006/n1986.pdf">N1986</a></td><td>是</td><td>支持构造函数委托链。</td></tr><tr><td>继承构造函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2540.htm">N2540</a></td><td>是</td><td>派生类可经<code>using Base::Base;</code>继承基类构造函数。</td></tr><tr><td>显式转换运算符</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2437.pdf">N2437</a></td><td>是</td><td>支持<code>explicit operator T</code>。</td></tr><tr><td>新字符类型</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2249.html">N2249</a></td><td>是</td><td>支持char16_t、char32_t作为算术类型参与运算。</td></tr><tr><td>Unicode字符串字面量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2442.htm">N2442</a></td><td>是</td><td>u8、u、U前缀字符串字面量可编译。</td></tr><tr><td>原始字符串字面量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2442.htm">N2442</a></td><td>是</td><td>R&quot;(...)&quot;内转义序列不生效，按字面字符处理。</td></tr><tr><td>字面量中的通用字符名</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2170.html">N2170</a></td><td>是</td><td>支持UCN的UTF-8落地形式。</td></tr><tr><td>用户自定义字面量</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2765.pdf">N2765</a></td><td>是</td><td>支持operator&quot;&quot;后缀字面量运算符，Device侧可定义并调用。</td></tr><tr><td>标准布局类型</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2342.htm">N2342</a></td><td>是</td><td><code>std::is_standard_layout</code>判定与标准一致，<code>&lt;type_traits&gt;</code>可在Device侧使用。</td></tr><tr><td>defaulted函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2346.htm">N2346</a></td><td>是</td><td>构造、拷贝、移动、赋值、析构均支持<code>= default</code>。</td></tr><tr><td>deleted函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2346.htm">N2346</a></td><td>是</td><td>支持<code>= delete</code>，可构造move-only类型。</td></tr><tr><td>扩展friend声明</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2005/n1791.pdf">N1791</a></td><td>是</td><td>支持模板友元不写<code>&lt;&gt;</code>的扩展形式。</td></tr><tr><td>扩展sizeof</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2253.html">N2253</a>、<a href="https://www.open-std.org/jtc1/sc22/wg21/docs/cwg_defects.html#850">DR850</a></td><td>是</td><td>支持类成员sizeof且无需实例，以及<code>sizeof...</code>参数包。</td></tr><tr><td>内联命名空间</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2535.htm">N2535</a></td><td>是</td><td>inline namespace成员对外直接可见，可用于版本管理。</td></tr><tr><td>非受限联合体</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2544.pdf">N2544</a></td><td>是</td><td>联合体成员可含非平凡成员与非静态数据成员初始化器。</td></tr><tr><td>局部与无名类型作为模板实参</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2657.htm">N2657</a></td><td>是</td><td>块作用域内定义的类型可作模板实参。</td></tr><tr><td>基于范围的for循环</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2009/n2930.html">N2930</a></td><td>是</td><td>数组与定义了begin、end的类型可用范围for遍历；Device侧数组遍历可用。</td></tr><tr><td>显式虚函数重载</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2009/n2928.htm">N2928</a>、<a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2010/n3206.htm">N3206</a>、<a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2011/n3272.htm">N3272</a></td><td>否</td><td>Device侧不支持虚函数</td></tr><tr><td>最小GC与泄漏检测支持</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2670.htm">N2670</a></td><td>否</td><td>不适用。</td></tr><tr><td>允许移动构造抛出异常（noexcept）</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2010/n3050.html">N3050</a></td><td>是</td><td>支持noexcept说明符与noexcept运算符，<code>static_assert(noexcept(f))</code>可用。</td></tr><tr><td>定义移动特殊成员函数</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2010/n3053.html">N3053</a></td><td>是</td><td>支持移动构造与移动赋值的定义、使用。</td></tr></tbody></table><p>下表汇总了Device侧对C++11并发相关特性的支持情况：</p><table><thead><tr><th>C++11特性</th><th>C++11 Proposal</th><th>是否支持</th><th>说明</th></tr></thead><tbody><tr><td>顺序点</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2239.html">N2239</a></td><td>否</td><td>C++11起以“先于”关系取代顺序点描述单线程内求值顺序（语言定义，非库设施）。Device侧编译器按同一规则实现指令流顺序，不提供顺序点相关的库设施。</td></tr><tr><td>原子操作</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2427.html">N2427</a></td><td>否</td><td><code>std::atomic</code>不可用；原子能力经SIMT原子API提供，如<code>asc_atomic_add</code>、<code>asc_atomic_cas</code>。</td></tr><tr><td>强比较与交换</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2748.html">N2748</a></td><td>否</td><td>CAS能力经<code>asc_atomic_cas</code>提供，非<code>std::atomic</code>接口。</td></tr><tr><td>双向栅栏</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2752.htm">N2752</a></td><td>否</td><td>内存栅栏经SIMT同步API提供，如<code>asc_threadfence</code>。</td></tr><tr><td>内存模型</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2429.htm">N2429</a></td><td>否</td><td>Device侧不实现C++标准内存模型。</td></tr><tr><td>数据依赖顺序：原子与内存模型</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2664.htm">N2664</a></td><td>否</td><td>Device侧不实现C++标准内存模型。</td></tr><tr><td>异常传播</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2179.html">N2179</a></td><td>否</td><td>Device侧不支持异常。</td></tr><tr><td>信号处理器中使用原子</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2547.htm">N2547</a></td><td>否</td><td>Device侧无信号处理模型。</td></tr><tr><td>线程局部存储</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2659.htm">N2659</a></td><td>否</td><td><code>thread_local</code>关键字不可用。</td></tr><tr><td>并发动态初始化与析构</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2008/n2660.htm">N2660</a></td><td>否</td><td>Device侧不支持动态初始化与析构的并发语义。</td></tr></tbody></table><p>下表汇总了Device侧对C++11收录的C99特性的支持情况：</p><table><thead><tr><th>C99特性</th><th>C++11 Proposal</th><th>支持情况</th><th>说明</th></tr></thead><tbody><tr><td><code>__func__</code>预定义标识符</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2007/n2340.htm">N2340</a></td><td>是</td><td>函数内隐式静态字符串数组可用。</td></tr><tr><td>C99预处理器</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2004/n1653.htm">N1653</a></td><td>是</td><td>支持可变参数宏<code>__VA_ARGS__</code>、记号粘贴<code>##</code>、字符串化<code>#</code>。GNU扩展<code>##__VA_ARGS__</code>空参吞并在可变参数为空时不可用，需以函数重载等方式替代。</td></tr><tr><td>long long</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2005/n1811.pdf">N1811</a></td><td>是</td><td>64位，支持LL、ULL后缀与宽位数算术。</td></tr><tr><td>扩展整型</td><td><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2006/n1988.pdf">N1988</a></td><td>是</td><td><code>&lt;stdint.h&gt;</code>、<code>&lt;cinttypes&gt;</code>可包含，<code>intmax_t</code>、<code>uintmax_t</code>、<code>INT64_C</code>与<code>int32_t</code>/<code>uint32_t</code>等定宽类型在Device侧可用。</td></tr></tbody></table></article></div>',1)])])}const i=d(c,[["render",p]]);export{f as __pageData,i as default};
